#!/usr/bin/env python3
from pathlib import Path
import subprocess
import re

MARK='MEMEFLOW_STRICT_ENTRY_ADMISSION_V1'
root=Path.cwd()
if (root/'memeflow-app').is_dir(): app=root/'memeflow-app'
elif (root/'app-server.mjs').is_file() and (root/'src').is_dir(): app=root
else: raise SystemExit('ERROR: memeflow-app not found. Run from the Replit project root.')
paths={'app':app/'app-server.mjs','gate':app/'src'/'settings-gate.mjs','liveeval':app/'src'/'liveeval.mjs','pkg':app/'package.json','test':app/'tests'/'strict-entry-admission.mjs','fresh':app/'tests'/'fresh-session-scanner.mjs'}
for k in ('app','gate','liveeval','pkg','fresh'):
    if not paths[k].exists(): raise SystemExit(f'ERROR: missing {paths[k]}')

def run(cmd,cwd=None):
    print('+',' '.join(map(str,cmd)))
    subprocess.run(cmd,cwd=cwd,check=True)

def replace_once(text,old,new,label):
    n=text.count(old)
    if n!=1: raise RuntimeError(f'PATCH ERROR [{label}]: expected exactly 1 anchor, found {n}')
    return text.replace(old,new,1)

def sub_once(text,pattern,repl,label):
    out,n=re.subn(pattern,repl,text,count=1,flags=re.S)
    if n!=1: raise RuntimeError(f'PATCH ERROR [{label}]: expected exactly 1 regex anchor, found {n}')
    return out

rel=[str(paths[k].relative_to(root)) for k in ('app','gate','liveeval','pkg','fresh')]
if paths['test'].exists(): rel.append(str(paths['test'].relative_to(root)))
dirty=subprocess.run(['git','status','--porcelain','--',*rel],cwd=root,text=True,capture_output=True,check=True).stdout.strip()
if dirty:
    print('ERROR: target files already have local changes:')
    print(dirty)
    print('Nothing was changed.')
    raise SystemExit(1)

originals={k:paths[k].read_text(encoding='utf-8') for k in ('app','gate','liveeval','pkg','fresh')}
test_existed=paths['test'].exists()
test_original=paths['test'].read_text(encoding='utf-8') if test_existed else None

GATE_ADD="\n// MEMEFLOW_STRICT_ENTRY_ADMISSION_V1\n// Entry Filters are the visibility/admission boundary for the scanner.\n//\n// A token is ADMITTED only when every currently knowable Entry Filter for that\n// user is PASS. A retryable FAIL (for example MC below minimum, holders below\n// minimum, token younger than minimum age) is PRE-ADMISSION PENDING: keep the\n// tiny WS state so it can improve, but do not create/show a scanner decision.\n//\n// Wallet funding/cluster checks are intentionally FINAL-ONLY. Their settings\n// remain enforced after BUY READY by the dedicated Solana RPC pre-open stage.\nconst PRE_ADMISSION_FINAL_ONLY_KEYS = new Set([\n  'maxSuspectedRiskyWalletsPct',\n  'maxInsidersPct'\n]);\n\nexport function evaluateEntryAdmission(token={},settings={},options={}){\n  const now=Number(options?.now)||Date.now();\n  void now;\n\n  const full=evaluateSettingsGate(token,settings);\n\n  const gates=(full.gates||[])\n    .filter(g=>!PRE_ADMISSION_FINAL_ONLY_KEYS.has(String(g?.key||'')));\n\n  const failedGates=gates.filter(g=>g?.status==='FAIL');\n  const waitingGates=gates.filter(g=>g?.status==='WAITING');\n\n  const hasStableFailure=failedGates.some(g=>g?.retryable!==true);\n  const hasRetryableFailure=failedGates.some(g=>g?.retryable===true);\n  const admitted=failedGates.length===0&&waitingGates.length===0;\n\n  let state='ADMITTED';\n  if(!admitted){\n    state=hasStableFailure?'REJECTED':'PENDING';\n  }\n\n  return {\n    admitted,\n    state,\n    gates,\n    failedGates,\n    waitingGates,\n    hasStableFailure,\n    hasRetryableFailure,\n    finalOnlyKeys:[...PRE_ADMISSION_FINAL_ONLY_KEYS],\n    reasons:[...failedGates,...waitingGates]\n      .map(g=>g?.reason)\n      .filter(Boolean)\n  };\n}\n\nexport function isEntryAdmitted(token={},settings={},options={}){\n  return evaluateEntryAdmission(token,settings,options).admitted===true;\n}\n"
HELPER_BLOCK="// MEMEFLOW_STRICT_ENTRY_ADMISSION_V1\nconst __mfEntryAdmissionState=new Map();\n\nfunction __mfEntryAdmissionForUser(\n  token,\n  uid,\n  settingsOverride=null,\n  now=Date.now()\n){\n  try{\n    const settings=\n      settingsOverride &&\n      typeof settingsOverride==='object'\n        ? settingsOverride\n        : (store.settings(uid)||{});\n\n    return evaluateEntryAdmission(token,settings,{now});\n  }catch(error){\n    return {\n      admitted:false,\n      state:'PENDING',\n      failedGates:[],\n      waitingGates:[],\n      hasStableFailure:false,\n      hasRetryableFailure:false,\n      reasons:['entry admission evaluation error']\n    };\n  }\n}\n\nfunction __mfClearDecisionForUserMint(uid,mint){\n  const key=String(uid||'')+':'+String(mint||'');\n  if(!uid||!mint)return false;\n\n  let removed=false;\n  if(store.state.decisions?.[key]){\n    delete store.state.decisions[key];\n    removed=true;\n  }\n\n  try{\n    if(store._uidDec?.[uid]?.has?.(key)){\n      store._uidDec[uid].delete(key);\n      removed=true;\n    }\n  }catch{}\n\n  return removed;\n}\n\nfunction __mfLiveEvalAdmissionCheck(token,settings,uid){\n  const admission=__mfEntryAdmissionForUser(token,uid,settings);\n  const key=String(uid||'')+':'+String(token?.mint||'');\n\n  if(uid&&token?.mint){\n    __mfEntryAdmissionState.set(key,admission?.admitted===true);\n  }\n\n  return admission;\n}\n\nfunction __mfAdmittedScannerTokensForUser(uid,now=Date.now()){\n  const settings=store.settings(uid)||{};\n  return __mfLiveScannerTokens(now)\n    .filter(token=>\n      __mfEntryAdmissionForUser(token,uid,settings,now)?.admitted===true\n    );\n}\n\nfunction __mfAnyActiveEntryAdmitted(token,now=Date.now()){\n  if(!token)return false;\n  const uids=__mfActiveScannerUserIds(now);\n  if(!uids.length)return false;\n\n  for(const uid of uids){\n    if(__mfEntryAdmissionForUser(token,uid,null,now)?.admitted===true){\n      return true;\n    }\n  }\n\n  return false;\n}\n\n"
NEW_EVAL="const evaluateAll=makeEvaluateForActiveUsers({\n  store,\n  metrics:liveEvalMetrics,\n  activeUserHoursMs:LIVE_EVAL_HOURS*3600000,\n  batchSize:LIVE_EVAL_BATCH,\n  delayMs:LIVE_EVAL_DELAY,\n  admissionCheck:__mfLiveEvalAdmissionCheck,\n  onDecision:(uid,token,decision)=>{\n    void __mfHandleDecision(uid,token,decision).catch(()=>{});\n  }\n});\n\n// A TradeEvent causes immediate admission re-check. This sweep exists only for\n// gates that can change without a trade event (most importantly minimum age).\n// It triggers a full evaluation only on a hidden -> admitted transition.\nconst __mfPreAdmissionSweepMs=Math.max(\n  1000,\n  Number(process.env.PRE_ADMISSION_SWEEP_MS||2000)\n);\n\nconst __mfPreAdmissionSweepTimer=setInterval(()=>{\n  try{\n    const now=Date.now();\n    const tokens=__mfLiveScannerTokens(now);\n    const uids=__mfActiveScannerUserIds(now);\n\n    if(!tokens.length||!uids.length)return;\n\n    const users=uids.map(uid=>({\n      uid,\n      settings:store.settings(uid)||{}\n    }));\n\n    for(const token of tokens){\n      let promote=false;\n\n      for(const row of users){\n        const key=row.uid+':'+token.mint;\n        const previous=__mfEntryAdmissionState.get(key);\n        const admission=__mfEntryAdmissionForUser(\n          token,\n          row.uid,\n          row.settings,\n          now\n        );\n        const admitted=admission?.admitted===true;\n\n        if(admitted&&previous!==true){\n          promote=true;\n        }else if(!admitted&&previous===true){\n          __mfClearDecisionForUserMint(row.uid,token.mint);\n        }\n\n        __mfEntryAdmissionState.set(key,admitted);\n      }\n\n      if(promote){\n        Promise.resolve(evaluateAll(token)).catch(()=>{});\n      }\n    }\n\n    if(__mfEntryAdmissionState.size>50000){\n      const active=new Set(uids);\n      const live=new Set(tokens.map(t=>String(t?.mint||'')));\n      for(const key of [...__mfEntryAdmissionState.keys()]){\n        const cut=String(key).lastIndexOf(':');\n        const uid=cut>=0?String(key).slice(0,cut):'';\n        const mint=cut>=0?String(key).slice(cut+1):'';\n        if(!active.has(uid)||!live.has(mint)){\n          __mfEntryAdmissionState.delete(key);\n        }\n      }\n    }\n  }catch{}\n},__mfPreAdmissionSweepMs);\n__mfPreAdmissionSweepTimer.unref?.();"
SHADOW_REPLACEMENT="function shadowValidateSettings(settings,limit=50){\n  const rows=__mfLiveScannerTokens()\n    .slice(0,Math.max(1,Math.min(200,limit)));\n\n  const counts={\n    WAITING:0,\n    WATCH:0,\n    'BUY READY':0,\n    BLOCKED:0,\n    EXPIRED:0\n  };\n  const admission={ADMITTED:0,PENDING:0,REJECTED:0};\n  const errors=[];\n\n  for(const token of rows){\n    try{\n      const gate=evaluateEntryAdmission(token,settings);\n      admission[gate.state]=(admission[gate.state]||0)+1;\n\n      if(gate.admitted!==true)continue;\n\n      const d=evaluate(token,settings);\n      counts[d.state]=(counts[d.state]||0)+1;\n    }catch(e){\n      errors.push({mint:token.mint||null,message:e.message});\n    }\n  }\n\n  return {\n    tested:rows.length,\n    admitted:admission.ADMITTED||0,\n    hidden:(admission.PENDING||0)+(admission.REJECTED||0),\n    admission,\n    counts,\n    errors\n  };\n}\n\nfunction reevaluateUser(uid){\n  const settings=store.settings(uid);\n  const tokens=__mfLiveScannerTokens();\n  const settingsVersion=\n    store.user(uid)?.settingsVersion||\n    store.user(uid)?.updatedAt||\n    Date.now();\n\n  let count=0,errors=0,hidden=0;\n  const states={WAITING:0,WATCH:0,BLOCKED:0,'BUY READY':0,EXPIRED:0};\n\n  for(const token of tokens){\n    try{\n      const admission=__mfEntryAdmissionForUser(token,uid,settings);\n\n      if(admission?.admitted!==true){\n        __mfClearDecisionForUserMint(uid,token.mint);\n        __mfEntryAdmissionState.set(uid+':'+token.mint,false);\n        hidden++;\n        continue;\n      }\n\n      __mfEntryAdmissionState.set(uid+':'+token.mint,true);\n\n      const d=evaluate(token,settings);\n      const saved={\n        ...d,\n        primaryReason:d.primaryReason,\n        settingsVersion,\n        reevaluatedAt:Date.now()\n      };\n\n      store.setDecision(uid,token.mint,saved);\n      states[d.state]=(states[d.state]||0)+1;\n\n      if(d.state==='BUY READY'){\n        void __mfHandleDecision(uid,token,saved).catch(()=>{});\n      }\n\n      count++;\n    }catch(_){\n      errors++;\n    }\n  }\n\n  return {count,hidden,errors,states,settingsVersion};\n}\n\n/* MEMEFLOW_NATIVE_AI_V46_BEGIN */"
TEST_TEXT="import assert from 'node:assert/strict';\nimport fs from 'node:fs';\n\nimport {\n  evaluateEntryAdmission\n} from '../src/settings-gate.mjs';\n\nimport {\n  makeLiveEvalMetrics,\n  makeEvaluateForActiveUsers\n} from '../src/liveeval.mjs';\n\nimport {defaultSettings} from '../src/settings.mjs';\n\nconst now=Date.now();\n\nconst strictSettings={\n  launchPlatforms:['pump'],\n  minMarketCapUsd:30000,\n  minHolders:30,\n  minTokenAgeMinutes:20,\n  maxTop10Pct:25,\n  maxDeveloperPct:20,\n  minBuyPressure:1.2,\n  requireAnySocial:true,\n  requireFreshHolderSnapshot:true,\n  maxSuspectedRiskyWalletsPct:35,\n  maxInsidersPct:25\n};\n\nconst tooEarly={\n  mint:'Early',\n  launchPlatform:'pump',\n  discoveredAt:now-90_000,\n  marketCapUsd:2600,\n  holderCount:5,\n  top10Pct:20,\n  developerPct:10,\n  buyPressure:2,\n  holderFresh:true,\n  twitterUrl:'https://x.com/example',\n  socialsKnown:true\n};\n\nconst earlyAdmission=evaluateEntryAdmission(tooEarly,strictSettings);\nassert.equal(earlyAdmission.admitted,false);\nassert.equal(earlyAdmission.state,'PENDING');\nassert.equal(earlyAdmission.hasStableFailure,false);\nassert.ok(earlyAdmission.failedGates.some(g=>g.key==='minMarketCapUsd'));\nassert.ok(earlyAdmission.failedGates.some(g=>g.key==='minHolders'));\nassert.ok(earlyAdmission.failedGates.some(g=>g.key==='minTokenAgeMinutes'));\n\nconst admitted={\n  ...tooEarly,\n  mint:'Admitted',\n  discoveredAt:now-(21*60_000),\n  marketCapUsd:35000,\n  holderCount:44,\n  top10Pct:18,\n  developerPct:7,\n  buyPressure:2.2\n};\n\nconst good=evaluateEntryAdmission(admitted,strictSettings);\nassert.equal(good.admitted,true);\nassert.equal(good.state,'ADMITTED');\n\nconst finalOnly=evaluateEntryAdmission(\n  {\n    ...admitted,\n    suspectedRiskyWalletsPct:99,\n    insidersPct:99\n  },\n  strictSettings\n);\nassert.equal(finalOnly.admitted,true);\nassert.ok(\n  finalOnly.gates.every(\n    g=>g.key!=='maxSuspectedRiskyWalletsPct'&&g.key!=='maxInsidersPct'\n  )\n);\n\nconst stable=evaluateEntryAdmission(\n  {\n    ...admitted,\n    name:'Definitely scam token'\n  },\n  {\n    ...strictSettings,\n    excludeKeywords:'scam'\n  }\n);\nassert.equal(stable.admitted,false);\nassert.equal(stable.state,'REJECTED');\nassert.equal(stable.hasStableFailure,true);\n\nconst missing=evaluateEntryAdmission(\n  {\n    mint:'Missing',\n    launchPlatform:'pump',\n    discoveredAt:now-(21*60_000)\n  },\n  strictSettings\n);\nassert.equal(missing.admitted,false);\nassert.equal(missing.state,'PENDING');\nassert.ok(missing.waitingGates.length>0);\n\nconst baseSettings={\n  ...defaultSettings(),\n  minHolders:0,\n  maxTop10Pct:null,\n  maxDeveloperPct:null,\n  minBuyPressure:0,\n  requireFreshHolderSnapshot:false,\n  minTokenAgeMinutes:0,\n  maxTokenAgeMinutes:null,\n  minScore:0,\n  minConfidence:0,\n  maxSuspectedRiskyWalletsPct:null,\n  maxInsidersPct:null\n};\n\nconst fakeStore={\n  state:{\n    users:{\n      allowed:{lastActiveAt:now,settingsVersion:1},\n      hidden:{lastActiveAt:now,settingsVersion:1}\n    },\n    decisions:{}\n  },\n  _uidDec:{},\n  settings(){return baseSettings},\n  setDecision(uid,mint,decision){\n    const key=uid+':'+mint;\n    this.state.decisions[key]={...decision,mint};\n    if(!this._uidDec[uid])this._uidDec[uid]=new Map();\n    this._uidDec[uid].set(key,this.state.decisions[key]);\n    return this.state.decisions[key];\n  }\n};\n\nconst metrics=makeLiveEvalMetrics();\nconst live=makeEvaluateForActiveUsers({\n  store:fakeStore,\n  metrics,\n  admissionCheck:(_token,_settings,uid)=>({\n    admitted:uid==='allowed'\n  })\n});\n\nawait live({\n  mint:'LiveMint',\n  priceSol:0.00001,\n  holderCount:50,\n  top10Pct:15,\n  developerPct:5,\n  buyPressure:2,\n  holderFresh:true,\n  qualityScore:80,\n  opportunityScore:70,\n  opportunityEvidenceReady:true,\n  opportunityTrendHealthy:true\n});\n\nassert.ok(fakeStore.state.decisions['allowed:LiveMint']);\nassert.equal(fakeStore.state.decisions['hidden:LiveMint'],undefined);\nassert.equal(metrics.entryAdmissionLastPassedUsers,1);\nassert.ok(metrics.entryAdmissionUsersHidden>=1);\n\nconst app=fs.readFileSync(\n  new URL('../app-server.mjs',import.meta.url),\n  'utf8'\n);\n\nassert.match(app,/MEMEFLOW_STRICT_ENTRY_ADMISSION_V1/);\nassert.match(app,/admissionCheck:__mfLiveEvalAdmissionCheck/);\nassert.match(app,/__mfAdmittedScannerTokensForUser\\(u\\.id\\)/);\nassert.match(app,/preAdmissionHidden:/);\nassert.match(app,/preAdmissionHiddenForUser:/);\n\nconst discovery=app.slice(\n  app.indexOf('function startDiscovery(i=0){'),\n  app.indexOf('function shadowValidateSettings')\n);\nassert.doesNotMatch(discovery,/scanWalletClusterRisk/);\n\nconsole.log('strict entry admission v1 ok');\n"

