    liveeval_text=replace_once(liveeval_text,'export function makeEvaluateForActiveUsers({\n  store,metrics,activeUserHoursMs=86400000,batchSize=25,delayMs=0,onDecision=null\n}){','export function makeEvaluateForActiveUsers({\n  store,metrics,activeUserHoursMs=86400000,batchSize=25,delayMs=0,\n  onDecision=null,admissionCheck=null\n}){','liveeval/signature')
    liveeval_text=replace_once(liveeval_text,'    const groups=new Map();\n    for(const uid of activeUids){\n      try{\n        const c=cachedSettings(uid);\n        let g=groups.get(c.key);\n        if(!g){g={settings:c.settings,uids:[]};groups.set(c.key,g)}\n        g.uids.push(uid);\n      }catch(e){recordError(e)}\n    }\n    metrics.livePolicyGroups=groups.size;\n',"    const groups=new Map();\n    let admittedUserCount=0;\n\n    for(const uid of activeUids){\n      try{\n        const c=cachedSettings(uid);\n\n        if(typeof admissionCheck==='function'){\n          metrics.entryAdmissionUsersChecked++;\n          const admission=admissionCheck(token,c.settings,uid);\n\n          if(admission?.admitted!==true){\n            metrics.entryAdmissionUsersHidden++;\n            const key=uid+':'+String(token?.mint||'');\n            if(store.state.decisions?.[key]){\n              delete store.state.decisions[key];\n              store._uidDec?.[uid]?.delete?.(key);\n              metrics.entryAdmissionDecisionsCleared++;\n            }\n            continue;\n          }\n\n          metrics.entryAdmissionUsersPassed++;\n        }\n\n        admittedUserCount++;\n        let g=groups.get(c.key);\n        if(!g){g={settings:c.settings,uids:[]};groups.set(c.key,g)}\n        g.uids.push(uid);\n      }catch(e){recordError(e)}\n    }\n\n    metrics.entryAdmissionLastPassedUsers=admittedUserCount;\n    metrics.livePolicyGroups=groups.size;\n",'liveeval/admission-before-grouping')
    liveeval_text=replace_once(liveeval_text,'    return {decisionLike:true,activeUsers:activeUids.length,evaluationsPerformed:activeUids.length,policyGroups:groups.size};','    return {\n      decisionLike:true,\n      activeUsers:activeUids.length,\n      admittedUsers:admittedUserCount,\n      evaluationsPerformed:admittedUserCount,\n      policyGroups:groups.size\n    };','liveeval/return')

    app_text=replace_once(app_text,"import {JsonStore,sessionId,defaults} from './src/store.mjs';import {RpcPool,validPubkey,decodeCurve,decodeCreateData,decodePumpCreate,decodePumpCreateEventLog,shouldExcludeMayhemCreate} from './src/solana.mjs';import {evaluate,tokenAgeMinutes} from './src/evaluate.mjs';import {evaluateSettingsAdmission,settingsContextSignature} from './src/settings-gate.mjs';import {validateSettings,PROFILE_PRESETS} from './src/settings.mjs';import {StripeBilling} from './src/billing.mjs';","import {JsonStore,sessionId,defaults} from './src/store.mjs';import {RpcPool,validPubkey,decodeCurve,decodeCreateData,decodePumpCreate,decodePumpCreateEventLog,shouldExcludeMayhemCreate} from './src/solana.mjs';import {evaluate,tokenAgeMinutes} from './src/evaluate.mjs';import {evaluateSettingsAdmission,evaluateEntryAdmission,settingsContextSignature} from './src/settings-gate.mjs';import {validateSettings,PROFILE_PRESETS} from './src/settings.mjs';import {StripeBilling} from './src/billing.mjs';",'app/import-entry-admission')
    app_text=replace_once(app_text,"function __mfAllActiveUsersStableBlocked(mint,now=Date.now()){\n  const uids=__mfActiveScannerUserIds(now);\n  if(!uids.length)return false;\n  for(const uid of uids){\n    const d=store.state.decisions?.[uid+':'+mint];\n    if(!d)return false;\n    if(d.state!=='BLOCKED'||d.settingsEvaluation?.hasStableFailure!==true)return false;\n  }\n  return true;\n}\n",'function __mfAllActiveUsersStableBlocked(mint,now=Date.now()){\n  const token=store.state.tokens?.[mint]||null;\n  if(!token)return true;\n\n  const uids=__mfActiveScannerUserIds(now);\n  if(!uids.length)return false;\n\n  for(const uid of uids){\n    const admission=__mfEntryAdmissionForUser(token,uid,null,now);\n    if(admission?.admitted===true)return false;\n    if(admission?.hasStableFailure!==true)return false;\n  }\n\n  return true;\n}\n','app/stable-prune-entry-semantics')
